import { createContext, useContext, useState, useEffect } from "react";
import { AuthContext } from "./AuthContext"; // pour récupérer le token

export const UserContext = createContext();

export const UserProvider = ({ children }) => {
  const { token } = useContext(AuthContext);
  const [userData, setUserData] = useState(null);
  const [loading, setLoading] = useState(true);

  // Format date → YYYY-MM-DD
  const formatDate = (d) => d.toISOString().split("T")[0];

  // Période par défaut : 4 dernières semaines
  const end = new Date();
  const start = new Date();
  start.setDate(end.getDate() - 28);

  const startDate = formatDate(start);
  const endDate = formatDate(end);

  useEffect(() => {
    if (!token) {
      setUserData(null);
      setLoading(false);
      return;
    }

    const fetchUserData = async () => {
      try {
        // 1) Récupérer profil + statistiques
        const infoRes = await fetch("http://localhost:8000/api/user-info", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!infoRes.ok) throw new Error("Erreur API user-info");
        const info = await infoRes.json();

        // 2) Récupérer les sessions filtrées
        const activityRes = await fetch(
          `http://localhost:8000/api/user-activity?startWeek=${startDate}&endWeek=${endDate}`,
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );
        if (!activityRes.ok) throw new Error("Erreur API user-activity");
        const sessions = await activityRes.json();

        // 3) Stocker toutes les données dans un seul objet
        setUserData({
          profile: info.profile,
          statistics: info.statistics,
          sessions: sessions, // 🔥 les vraies sessions
          startDate,
          endDate,
        });
      } catch (err) {
        console.error("Erreur UserContext :", err);
        setUserData(null);
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, [token]);

  return (
    <UserContext.Provider value={{ userData, loading }}>
      {children}
    </UserContext.Provider>
  );
};

export const useUser = () => useContext(UserContext);
